// Pseudo-code skeleton for online ICA frame processing
function processFrame(frame, state){
  const wf = adaptiveSTFT(frame, state.window);
  const whitened = whiten(wf, state.weights);
  const sources = perBinICA(whitened, state.demixer);
  const permuted = crossBinPermute(sources, state.tracker);
  return updateState(state, permuted);
}
```

